            "CREATE TABLE local_watchlist_alert_rules (\n                id INTEGER PRIMARY KEY AUTOINCREMENT,\n                job_id INTEGER,\n                name TEXT NOT NULL,\n                enabled INTEGER NOT NULL DEFAULT 1,\n                condition_type TEXT NOT NULL,\n                condition_value_json TEXT NOT NULL DEFAULT '{}',\n                severity TEXT NOT NULL DEFAULT 'warning',\n                created_at TEXT NOT NULL,\n                updated_at TEXT NOT NULL,\n                FOREIGN KEY (job_id) REFERENCES subscriptions(id) ON DELETE CASCADE\n            )",
            "CREATE TABLE local_watchlist_runs (\n                id INTEGER PRIMARY KEY AUTOINCREMENT,\n                source_id INTEGER NOT NULL,\n                job_id INTEGER,\n                batch_id TEXT,\n                status TEXT NOT NULL,\n                started_at TEXT,\n                finished_at TEXT,\n                stats_json TEXT,\n                error_msg TEXT,\n                log_text TEXT,\n                created_at TEXT NOT NULL,\n                updated_at TEXT NOT NULL,\n                FOREIGN KEY (source_id) REFERENCES subscriptions(id) ON DELETE CASCADE\n            )",
            "CREATE TABLE message_attachments(\n  message_id   TEXT    NOT NULL REFERENCES messages(id) ON DELETE CASCADE ON UPDATE CASCADE,\n  position     INTEGER NOT NULL CHECK (position >= 1),\n  data         BLOB    NOT NULL,\n  mime_type    TEXT    NOT NULL,\n  display_name TEXT    NOT NULL DEFAULT '',\n  PRIMARY KEY (message_id, position)\n)",
            "CREATE TABLE message_generation_metadata(\n  message_id      TEXT    NOT NULL REFERENCES messages(id) ON DELETE CASCADE ON UPDATE CASCADE,\n  position        INTEGER NOT NULL CHECK (position >= 0),\n  prompt          TEXT    NOT NULL,\n  negative_prompt TEXT    NOT NULL DEFAULT '',\n  backend         TEXT    NOT NULL,\n  model           TEXT,\n  seed            INTEGER,\n  style           TEXT,\n  params_json     TEXT    NOT NULL DEFAULT '{}',\n  created_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (message_id, position)\n)",
            "CREATE TABLE message_trajectory_metadata (\n    message_id TEXT NOT NULL,\n    conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,\n    turn_id TEXT NOT NULL,\n    seq INTEGER NOT NULL,\n    event_kind TEXT NOT NULL,\n    step_started_at REAL,\n    first_token_at REAL,\n    completed_at REAL,\n    model TEXT,\n    provider TEXT,\n    payload_json TEXT,\n    PRIMARY KEY (message_id, event_kind, seq),\n    FOREIGN KEY (message_id) REFERENCES messages(id) ON DELETE CASCADE\n)",
            "CREATE TABLE messages(\n  id                TEXT PRIMARY KEY,                 /* UUID */\n  conversation_id   TEXT  NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,\n  parent_message_id TEXT  REFERENCES messages(id)     ON DELETE SET NULL,\n  sender            TEXT  NOT NULL,\n  content           TEXT  NOT NULL, -- Text content of the message\n  image_data        BLOB DEFAULT NULL,\n  image_mime_type   TEXT DEFAULT NULL,\n  timestamp         DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  ranking           INTEGER,\n  last_modified     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  deleted           BOOLEAN NOT NULL DEFAULT 0,\n  client_id         TEXT    NOT NULL,\n  version           INTEGER NOT NULL DEFAULT 1\n, feedback TEXT, role TEXT DEFAULT 'assistant', variant_of TEXT REFERENCES messages(id) ON DELETE CASCADE, variant_number INTEGER DEFAULT 1, is_selected_variant BOOLEAN DEFAULT 1, total_variants INTEGER DEFAULT 1, usage_json TEXT DEFAULT NULL, metadata_json TEXT DEFAULT NULL, provider_continuation_json TEXT DEFAULT NULL)",
            "CREATE VIRTUAL TABLE messages_fts\nUSING fts5(\n  content,\n  content='messages',\n  content_rowid='rowid'\n)",
